        title: "幕间　爱操心的公爵千金与妹妹",
        content:
            `<p>「卡迪雅，你为什么要压下哥哥出色表现所引起的骚动？」</p>
<p>「苏，你觉得俊希望看到那种情况吗？」</p>
<p>「不觉得。可是……卡迪雅好奸诈。说，你跟哥哥到底是什么关系？」</p>
<p>「什么关系……不就是朋友吗？你怎么这么问？」</p>
<p>「骗人。你们不是普通朋友吧？那个叫作老师的精灵也是。圣女候选人和下任剑帝也是。你们到底是什么人？」</p>
<p>「这是应该从我口中告诉你的事情吗？」</p>
<p>「什么意思？」</p>
<p>「你真的想从我口中听到这个问题的答案？」</p>
<p>「这个嘛……」</p>
<p>「这种事还是去问俊本人吧。」</p>
<p>「可是……」</p>
<p>「虽然由我来说明也无所谓，但你有办法接受吗？」</p>
<p>「我能接受。」</p>
<p>「向我问这个问题只是逃避。难道你对俊的心意就只有这点程度？」</p>
<p>「才没有那种事呢！」</p>
<p>「那就不要问我，去问俊吧。这样对你和俊都好。」</p>
<p>「也许你说的对……」</p>
<p>「你现在抱持着什么样的感情，我大概能够体会。正因为如此，难道你不觉得应该把那份感情宣泄在他本人身上？」</p>
<p>「……我知道了，对不起。还有，谢谢你。」</p>
<p>「不客气。啊，顺便告诉你，我们之间确实有着特殊关系，但并没有恋爱方面的感情。这点你大可放心。」</p>
<p>「呜……嗯……」</p>
<p>「怎么了？你怎么回答得这么不干不脆？」</p>
<p>「没什么。你好像还没有自觉，所以我不该多嘴。」</p>
<p>「嗯……？」</p>
<p>「为什么我要推说不定会成为自己情敌的家伙一把……」</p>
<p>「咦？你说什么？」</p>
<p>「没什么。」</p>
<p><br/></p>
<p>「虽然把问题全丢给俊，但这样应该不算过分吧。毕竟这是他们兄妹的问题，不该把毫无关系的我卷进去。没错，这件事与我无关，与我无关……不过明天还是跟俊说一声吧。」</p>`
